            "p": "干支が変わるポイントは、太陽暦の1月1日でも旧正月でもありません。サジュで年を変える基準は**立春**です。したがって、1月初めや2月に生まれた人は、カレンダーが示す干支とは異なる干支を持つことがあります。"
