            "p": "このため、入力画面で干支を選択せずに生年月日だけを尋ねます。サジュエンジンが年を計算するとき、立春の境界に自動的に合わせます。直接選択した場合、2月初めに生まれた人は実際の干支と一致しない干支を選ぶことになります。"
